CREATE TABLE crm_customer_master (id uuid PRIMARY KEY, tenant_id uuid NOT NULL, owner_id uuid, name text, email text, company text, domain text, phone text, country text, stage text NOT NULL, status text NOT NULL, sources jsonb NOT NULL DEFAULT '[]', tags jsonb NOT NULL DEFAULT '[]', profile jsonb NOT NULL DEFAULT '{}', last_follow_up_at timestamptz, merged_into uuid, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE crm_inquiries (id uuid PRIMARY KEY, tenant_id uuid NOT NULL, customer_id uuid NOT NULL, source text NOT NULL, subject text NOT NULL, content text, status text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE crm_timeline_events (id uuid PRIMARY KEY, tenant_id uuid NOT NULL, customer_id uuid NOT NULL, event_type text NOT NULL, channel text NOT NULL, summary text NOT NULL, payload jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE crm_followup_tasks (id uuid PRIMARY KEY, tenant_id uuid NOT NULL, customer_id uuid NOT NULL, owner_id uuid NOT NULL, title text NOT NULL, due_at timestamptz NOT NULL, status text NOT NULL DEFAULT 'todo');
CREATE TABLE crm_duplicate_candidates (id uuid PRIMARY KEY, tenant_id uuid NOT NULL, left_id uuid NOT NULL, right_id uuid NOT NULL, score numeric(4,3) NOT NULL, reason text NOT NULL, status text NOT NULL DEFAULT 'pending');
CREATE INDEX crm_customer_scope ON crm_customer_master(tenant_id,owner_id,status,stage);
